export default function solve(params) {
  const N = 26, MARGIN = 1e-9;
  let R = 1 / Math.sqrt(N * Math.PI / 4);
  let step = 2 * R;
  let cols = Math.floor(1 / step);
  let spacing = 1 / cols;
  R = spacing * 0.48;
  let circles = [];
  for (let row = 0; circles.length < N; row++) {
    let y = (row + 0.5) * spacing;
    if (y + R > 1) break;
    let offset = (row % 2) * spacing * 0.5;
    for (let col = 0; circles.length < N; col++) {
      let x = offset + (col + 0.5) * spacing;
      if (x - R < 0 || x + R > 1) continue;
      circles.push([x, y, R]);
    }
  }
  while (circles.length < N) circles.push([0.5, 0.5, 0.01]);

  function sumR(cs) { let s = 0; for (let c of cs) s += c[2]; return s; }
  function valid(cs) {
    for (let i = 0; i < N; i++) {
      let [x,y,r] = cs[i];
      if (x - r < -MARGIN || x + r > 1 + MARGIN || y - r < -MARGIN || y + r > 1 + MARGIN || r <= 0) return false;
      for (let j = i + 1; j < N; j++) {
        let [x2,y2,r2] = cs[j];
        let dx = x - x2, dy = y - y2;
        if (dx * dx + dy * dy < (r + r2 - MARGIN) * (r + r2 - MARGIN)) return false;
      }
    }
    return true;
  }

  let best = circles.map(c => [...c]);
  let bestSum = sumR(best);
  let current = circles.map(c => [...c]);
  let currentSum = bestSum;

  let T = 0.1, cooling = 0.99999, iters = 20000;
  for (let iter = 0; iter < iters; iter++) {
    let idx = Math.floor(Math.random() * N);
    let ci = current[idx];
    let nx = Math.min(1 - ci[2], Math.max(ci[2], ci[0] + (Math.random() - 0.5) * 0.02));
    let ny = Math.min(1 - ci[2], Math.max(ci[2], ci[1] + (Math.random() - 0.5) * 0.02));
    let nr = Math.min(Math.min(nx, 1 - nx), Math.min(ny, 1 - ny));
    nr = Math.min(nr, ci[2] * Math.exp((Math.random() - 0.5) * 0.1));
    if (nr < 0.001) nr = 0.001;
    if (nx - nr < 0 || nx + nr > 1 || ny - nr < 0 || ny + nr > 1) continue;

    let oldX = ci[0], oldY = ci[1], oldR = ci[2];
    ci[0] = nx; ci[1] = ny; ci[2] = nr;

    let violated = false;
    for (let j = 0; j < N; j++) {
      if (j === idx) continue;
      let cj = current[j];
      let dx = nx - cj[0], dy = ny - cj[1];
      let minDist = nr + cj[2];
      if (dx * dx + dy * dy < minDist * minDist) {
        let overlap = minDist - Math.sqrt(dx*dx + dy*dy);
        if (nr <= cj[2]) {
          nr -= overlap * 0.5;
          if (nr < 0.001) { violated = true; break; }
          ci[2] = nr;
          if (nx - nr < 0 || nx + nr > 1 || ny - nr < 0 || ny + nr > 1) { violated = true; break; }
        } else {
          let shrink = cj[2] - overlap * 0.5;
          if (shrink < 0.001) { violated = true; break; }
          for (let k = 0; k < N; k++) {
            if (k === idx) continue;
            let ck = current[k];
            let dx2 = cj[0] - ck[0], dy2 = cj[1] - ck[1];
            if (dx2*dx2 + dy2*dy2 < (shrink + ck[2])*(shrink + ck[2])) { violated = true; break; }
          }
          if (violated) break;
          cj[2] = shrink;
        }
      }
    }
    if (violated) { ci[0] = oldX; ci[1] = oldY; ci[2] = oldR; continue; }

    let newSum = sumR(current);
    if (newSum > currentSum || Math.random() < Math.exp((newSum - currentSum) / T)) {
      currentSum = newSum;
      if (newSum > bestSum) {
        best = current.map(c => [...c]);
        bestSum = newSum;
      }
    } else {
      ci[0] = oldX; ci[1] = oldY; ci[2] = oldR;
    }
    T *= cooling;
  }

  for (let iter = 0; iter < 5000; iter++) {
    let idx = Math.floor(Math.random() * N);
    let ci = best[idx];
    let nr = ci[2] * 1.001;
    if (nr > 0.5) continue;
    if (ci[0] - nr < 0 || ci[0] + nr > 1 || ci[1] - nr < 0 || ci[1] + nr > 1) continue;
    let ok = true;
    for (let j = 0; j < N; j++) {
      if (j === idx) continue;
      let cj = best[j];
      let dx = ci[0] - cj[0], dy = ci[1] - cj[1];
      if (dx*dx + dy*dy < (nr + cj[2])*(nr + cj[2])) { ok = false; break; }
    }
    if (ok) { ci[2] = nr; bestSum = sumR(best); }
  }

  for (let i = 0; i < N; i++) {
    let c = best[i];
    let r = c[2];
    while (r > 0.001) {
      let nr = r * 0.999;
      let ok = true;
      if (c[0] - nr < 0 || c[0] + nr > 1 || c[1] - nr < 0 || c[1] + nr > 1) { ok = false; }
      if (ok) {
        for (let j = 0; j < N; j++) {
          if (j === i) continue;
          let cj = best[j];
          let dx = c[0] - cj[0], dy = c[1] - cj[1];
          if (dx*dx + dy*dy < (nr + cj[2])*(nr + cj[2])) { ok = false; break; }
        }
      }
      if (ok) { c[2] = nr; break; }
      r = nr;
    }
  }

  if (!valid(best)) {
    for (let iter = 0; iter < 100; iter++) {
      for (let i = 0; i < N; i++) {
        let ci = best[i];
        for (let j = i+1; j < N; j++) {
          let cj = best[j];
          let dx = ci[0] - cj[0], dy = ci[1] - cj[1];
          let minDist = ci[2] + cj[2];
          let dist = Math.sqrt(dx*dx + dy*dy);
          if (dist < minDist) {
            let overlap = minDist - dist;
            if (ci[2] <= cj[2]) { ci[2] -= overlap * 0.5; if (ci[2] < 0.001) ci[2] = 0.001; }
            else { cj[2] -= overlap * 0.5; if (cj[2] < 0.001) cj[2] = 0.001; }
          }
        }
      }
    }
  }

  for (let i = 0; i < N; i++) {
    let c = best[i];
    let maxR = Math.min(c[0], 1 - c[0], c[1], 1 - c[1]);
    for (let j = 0; j < N; j++) {
      if (j === i) continue;
      let cj = best[j];
      let dx = c[0] - cj[0], dy = c[1] - cj[1];
      let dist = Math.sqrt(dx*dx + dy*dy);
      if (dist > 0) { maxR = Math.min(maxR, dist - cj[2] - MARGIN); }
    }
    c[2] = Math.max(0.001, Math.min(c[2], maxR));
  }

  return best;
}

export default function solve(params) {
  const N = 26, MARGIN = 1e-9;
  let circles = [];
  // hexagonal lattice init
  let r0 = 0.098;
  let dx = r0 * 2, dy = r0 * Math.sqrt(3);
  for (let row = 0; circles.length < N; row++) {
    let y = 0.02 + row * dy;
    if (y + r0 > 1 - 0.02) break;
    let offset = (row % 2) * dx * 0.5;
    for (let col = 0; circles.length < N; col++) {
      let x = 0.02 + offset + col * dx;
      if (x + r0 > 1 - 0.02) continue;
      circles.push([x, y, r0]);
    }
  }
  while (circles.length < N) circles.push([0.5 + (Math.random()-0.5)*0.3, 0.5 + (Math.random()-0.5)*0.3, 0.05]);

  function sumR(cs) { let s = 0; for (let c of cs) s += c[2]; return s; }

  let best = circles.map(c => [...c]);
  let bestSum = sumR(best);
  let cur = circles.map(c => [...c]);
  let curSum = bestSum;
  let T = 0.5, iters = 50000;

  for (let iter = 0; iter < iters; iter++) {
    let idx = Math.floor(Math.random() * N);
    let ci = cur[idx];
    let nx = ci[0] + (Math.random() - 0.5) * 0.02;
    let ny = ci[1] + (Math.random() - 0.5) * 0.02;
    let nr = ci[2] * Math.exp((Math.random() - 0.5) * 0.2);
    if (nr < 0.01) nr = 0.01;
    if (nx - nr < MARGIN || nx + nr > 1 - MARGIN || ny - nr < MARGIN || ny + nr > 1 - MARGIN) continue;

    let ok = true;
    for (let j = 0; j < N; j++) {
      if (j === idx) continue;
      let cj = cur[j];
      let dx = nx - cj[0], dy = ny - cj[1];
      if (dx*dx + dy*dy < (nr + cj[2] + MARGIN) * (nr + cj[2] + MARGIN)) { ok = false; break; }
    }
    if (!ok) continue;

    let oldX = ci[0], oldY = ci[1], oldR = ci[2];
    ci[0] = nx; ci[1] = ny; ci[2] = nr;
    let newSum = curSum - oldR + nr;

    if (newSum > curSum || Math.random() < Math.exp((newSum - curSum) / T)) {
      curSum = newSum;
      if (newSum > bestSum) {
        best = cur.map(c => [...c]);
        bestSum = newSum;
      }
    } else {
      ci[0] = oldX; ci[1] = oldY; ci[2] = oldR;
    }
    T *= 0.99999;
  }

  // greedy radius expansion
  for (let i = 0; i < 20; i++) {
    for (let k = 0; k < N; k++) {
      let ci = best[k];
      let maxR = Math.min(ci[0], 1 - ci[0], ci[1], 1 - ci[1]);
      for (let j = 0; j < N; j++) {
        if (j === k) continue;
        let cj = best[j];
        let dx = ci[0] - cj[0], dy = ci[1] - cj[1];
        let dist = Math.sqrt(dx*dx + dy*dy);
        if (dist > MARGIN) maxR = Math.min(maxR, dist - cj[2] - MARGIN);
      }
      if (maxR > ci[2] + MARGIN) ci[2] = maxR;
    }
  }

  // final repair: shrink any overlaps
  let repaired = true;
  for (let iter = 0; iter < 200 && repaired; iter++) {
    repaired = false;
    for (let i = 0; i < N; i++) {
      let ci = best[i];
      let maxR = Math.min(ci[0], 1 - ci[0], ci[1], 1 - ci[1]);
      for (let j = 0; j < N; j++) {
        if (j === i) continue;
        let cj = best[j];
        let dx = ci[0] - cj[0], dy = ci[1] - cj[1];
        let dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < MARGIN) { maxR = 0; break; }
        let allowed = dist - cj[2] - MARGIN;
        if (allowed < maxR) maxR = allowed;
      }
      if (maxR < ci[2] - MARGIN) { ci[2] = Math.max(0.001, maxR); repaired = true; }
    }
  }

  return best;
}

export default function solve(params) {
  const N = 26, MARGIN = 1e-8;
  let circles = [];

  // Lay out circles in a hexagonal grid with ~0.1 radius
  let spacing = 0.09 * 2; // initial try
  let maxR = 0.09;
  let dy = maxR * Math.sqrt(3);
  let dx = maxR * 2;

  for (let row = 0; circles.length < N; row++) {
    let y = MARGIN + row * dy;
    if (y + maxR > 1 - MARGIN) break;
    let offset = (row % 2) * dx * 0.5;
    for (let col = 0; circles.length < N; col++) {
      let x = MARGIN + offset + col * dx;
      if (x + maxR > 1 - MARGIN) continue;
      circles.push([x, y, maxR]);
    }
  }
  while (circles.length < N) {
    circles.push([0.15 + Math.random()*0.7, 0.15 + Math.random()*0.7, 0.02]);
  }

  let cur = circles.map(c => [...c]);
  let best = cur.map(c => [...c]);
  let curSum = 0; for (let c of cur) curSum += c[2];
  let bestSum = curSum;

  let T = 0.1;
  let iters = 80000;

  for (let iter = 0; iter < iters; iter++) {
    let idx = Math.floor(Math.random() * N);
    let c = cur[idx];

    // Perturb: small position shift, multiplicative radius change
    let nx = c[0] + (Math.random() - 0.5) * 0.015;
    let ny = c[1] + (Math.random() - 0.5) * 0.015;
    let nr = c[2] * (0.99 + Math.random() * 0.02);

    // Bound check (strict)
    if (nr < 0.001) nr = 0.001;
    if (nx - nr < MARGIN || nx + nr > 1 - MARGIN || ny - nr < MARGIN || ny + nr > 1 - MARGIN) continue;

    // Overlap check
    let ok = true;
    for (let j = 0; j < N; j++) {
      if (j === idx) continue;
      let cj = cur[j];
      let dx = nx - cj[0], dy = ny - cj[1];
      let minDist = nr + cj[2] + MARGIN;
      if (dx*dx + dy*dy < minDist * minDist) { ok = false; break; }
    }
    if (!ok) continue;

    let oldX = c[0], oldY = c[1], oldR = c[2];
    let newSum = curSum - oldR + nr;

    if (newSum > curSum || Math.random() < Math.exp((newSum - curSum) / T)) {
      c[0] = nx; c[1] = ny; c[2] = nr;
      curSum = newSum;
      if (newSum > bestSum) {
        best = cur.map(c => [...c]);
        bestSum = newSum;
      }
    } else {
      // restore
      c[0] = oldX; c[1] = oldY; c[2] = oldR;
    }
    T *= 0.99995;
  }

  // Post-processing: maximize radii
  for (let pass = 0; pass < 10; pass++) {
    for (let i = 0; i < N; i++) {
      let c = best[i];
      // compute max possible radius given neighbors and square bounds
      let maxR = Math.min(c[0], 1 - c[0], c[1], 1 - c[1]) - MARGIN;
      for (let j = 0; j < N; j++) {
        if (j === i) continue;
        let cj = best[j];
        let dx = c[0] - cj[0], dy = c[1] - cj[1];
        let d = Math.sqrt(dx*dx + dy*dy);
        let limit = d - cj[2] - MARGIN;
        if (limit < maxR) maxR = limit;
      }
      if (maxR > c[2] + MARGIN) c[2] = maxR;
      else if (maxR < c[2] - 1e-10) c[2] = Math.max(0.001, maxR);
    }
  }

  return best;
}

