    [0.106050061642,0.519543947785,0.105522999668]
  ];

  // Function to compute the maximum feasible radius for a given circle at its current position
  function maxRadius(idx, config) {
    let x = config[idx][0], y = config[idx][1];
    let r = Math.min(x, 1 - x, y, 1 - y) - margin;
    for (let j = 0; j < n; j++) {
      if (j === idx) continue;
      let dx = x - config[j][0];
      let dy = y - config[j][1];
      let dist = Math.sqrt(dx * dx + dy * dy);
      r = Math.min(r, dist - config[j][2] - margin);
    }
    return Math.max(0.001, r);
  }

  // Compute sum of radii
  function totalSum(config) {
    let s = 0;
    for (let i = 0; i < n; i++) s += config[i][2];
    return s;
  }

  // Initialize best sum and current state
  let bestSum = totalSum(best);
  let current = best.map(c => [...c]);
  let currentSum = bestSum;

  // Simulated annealing parameters
  const maxIter = 100000;
  const T0 = 0.01;
  const T1 = 1e-6;

  for (let it = 0; it < maxIter; it++) {
    if (Date.now() - t0 > timeLimit) break;

    // Create candidate by perturbing one circle's position and radius
    let cand = current.map(c => [...c]);
    let idx = Math.floor(Math.random() * n);

    // Move to a new random position within the square
    cand[idx][0] = margin + Math.random() * (1 - 2 * margin);
    cand[idx][1] = margin + Math.random() * (1 - 2 * margin);

    // Recompute radius for the moved circle
    cand[idx][2] = maxRadius(idx, cand);

    // Also slightly adjust other circles' radii to improve sum
    // For each other circle, see if we can grow it
    for (let j = 0; j < n; j++) {
      if (j === idx) continue;
      let oldR = cand[j][2];
      cand[j][2] = maxRadius(j, cand);
      // If the radius decreased (due to the moved circle), don't accept the decrease
      // But we already computed maxRadius based on current configuration, so it's the best we can do
    }

    let newSum = totalSum(cand);

    // Temperature schedule
    let T = T0 * Math.pow(T1 / T0, it / maxIter);

    if (newSum > currentSum || Math.random() < Math.exp((newSum - currentSum) / T)) {
      current = cand;
      currentSum = newSum;
      if (newSum > bestSum) {
        bestSum = newSum;
        best = cand.map(c => [...c]);
      }
    }
  }

  // Final repair pass: grow all radii to their maximum feasible values
  let improved = true;
  while (improved) {
    improved = false;
    for (let i = 0; i < n; i++) {
      let oldR = best[i][2];
      best[i][2] = maxRadius(i, best);
      if (best[i][2] > oldR + 1e-12) {
        improved = true;
      } else {
        best[i][2] = oldR;
      }
    }
  }

  return best;
}

