      c[0] = origX;
      newR = Math.min(c[0], 1 - c[0], c[1], 1 - c[1]) - margin;
      for (let j = 0; j < n; j++) {
        if (j === i) continue;
        let dx = c[0] - cand[j][0], dy = c[1] - cand[j][1];
        let d = Math.sqrt(dx * dx + dy * dy);
        newR = Math.min(newR, d - cand[j][2] - margin);
      }

      // gradient w.r.t. y
      let origY = c[1];
      c[1] = Math.min(1 - margin, Math.max(margin, c[1] + eps));
      let gradY = (Math.min(c[0], 1 - c[0], c[1], 1 - c[1]) - margin - oldR) / eps;
      for (let j = 0; j < n; j++) {
        if (j === i) continue;
        let dx = c[0] - cand[j][0], dy = c[1] - cand[j][1];
        let d = Math.sqrt(dx * dx + dy * dy);
        let r = d - cand[j][2] - margin;
        gradY = Math.min(gradY, (r - oldR) / eps);
      }
      c[1] = origY;

      let norm = Math.sqrt(gradX * gradX + gradY * gradY);
      if (norm < 1e-10) continue;

      let step = Math.min(0.01, oldR / (norm + 1e-10));
      let nx = c[0] + step * gradX / norm;
      let ny = c[1] + step * gradY / norm;
      nx = Math.max(margin, Math.min(1 - margin, nx));
      ny = Math.max(margin, Math.min(1 - margin, ny));

      if (Math.abs(nx - c[0]) > 1e-12 || Math.abs(ny - c[1]) > 1e-12) {
