        c[1] = ny;
        improved = true;
      }
    }

    computeRadii(cand);
    let newSum = cand.reduce((s,c) => s + c[2], 0);

    if (newSum > currentSum + 1e-12) {
      current = cand;
      currentSum = newSum;
      if (newSum > bestSum) {
        bestSum = newSum;
        best = cand.map(c => [...c]);
      }
    } else {
      // Accept with small probability to escape local optima
      if (Math.random() < 0.01) {
        current = cand;
        currentSum = newSum;
      }
    }
  }

  // Final repair pass
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++) {
