        r = Math.min(r, d - best[j][2] - margin);
      }
      let newR = Math.max(1e-9, r);
      if (newR > oldR) {
        best[i][2] = newR;
        changed = true;
      } else {
        best[i][2] = oldR;
      }
    }
  }

  return best;
}

