      }
      rings = Object.values(ringGroups).filter(g => g.length >= 2);
    } else if (newSum > oldSum + tiny) {
      current = cand.map(c => [...c]);
    } else if (Math.random() < Math.exp((newSum - oldSum) / Math.max(temperature, minTemp))) {
      current = cand.map(c => [...c]);
    }

    stepSize = Math.max(minStep, stepSize * stepDecay);
    temperature = Math.max(minTemp, temperature * tempDecay);
  }

  let refined = best.map(c => [...c]);
  computeRadii(refined);
  let refinedSum = refined.reduce((s, c) => s + c[2], 0);

  const searchStep = 2e-5;
  const dirs = [[searchStep,0],[-searchStep,0],[0,searchStep],[0,-searchStep],
                [searchStep,searchStep],[searchStep,-searchStep],[-searchStep,searchStep],[-searchStep,-searchStep]];

