      }

      if (bestMove) {
        refined[i][0] = bestMove[0];
        refined[i][1] = bestMove[1];
        refinedSum = bestMoveSum;
        improved = true;
      }
    }
    if (!improved) break;
  }

  computeRadii(refined);

  if (refined.reduce((s, c) => s + c[2], 0) > bestSum) {
    return refined;
  }
  return best;
