  function computeRadii(config){
    for(let it=0;it<30;it++){
      let ch=false;
      for(let i=0;i<n;i++){
        const c=config[i];
        let r=Math.min(c[0],1-c[0],c[1],1-c[1])-margin;
        for(let j=0;j<n;j++){
          if(j===i)continue;
          const dx=c[0]-config[j][0],dy=c[1]-config[j][1];
          const d=Math.sqrt(dx*dx+dy*dy);
          const lim=d-config[j][2]-margin;
          if(lim<r)r=lim;
        }
        if(r<1e-12)r=1e-12;
        if(Math.abs(r-c[2])>tiny){c[2]=r;ch=true;}
      }
      if(!ch)break;
    }
  }

  function sum(c){let s=0;for(let i=0;i<n;i++)s+=c[i][2];return s;}

  const dirs=[];
  for(let a=0;a<32;a++){
    const ang=(a/32)*2*Math.PI;
    dirs.push([Math.cos(ang),Math.sin(ang)]);
  }

  computeRadii(best);
  let bestSum=sum(best);
  const trace=[[0,bestSum]];
  let current=best.map(c=>[...c]);
  let curSum=bestSum;
  let temp=2e-4,stuck=0,iter=0,lastLog=t0;

  while(Date.now()-t0<180000){
    iter++;
    const cand=current.map(c=>[...c]);
    let rnd=Math.random();

    if(rnd<0.6){
      const idx=Math.floor(Math.random()*n);
      const ang=Math.random()*2*Math.PI;
      const dist=Math.random()*0.02;
      cand[idx][0]=Math.max(margin,Math.min(1-margin,cand[idx][0]+Math.cos(ang)*dist));
      cand[idx][1]=Math.max(margin,Math.min(1-margin,cand[idx][1]+Math.sin(ang)*dist));
    } else if(rnd<0.9){
      const ci=Math.floor(Math.random()*n);
      const cx=cand[ci][0],cy=cand[ci][1];
      const cl=[ci];
      for(let i=0;i<n;i++){
        if(i===ci)continue;
        const dx=cand[i][0]-cx,dy=cand[i][1]-cy;
        if(dx*dx+dy*dy<0.04)cl.push(i);
      }
      if(cl.length>=3){
        const angle=(Math.random()-0.5)*0.25;
        const ca=Math.cos(angle),sa=Math.sin(angle);
        for(const idx of cl){
          const dx=cand[idx][0]-cx,dy=cand[idx][1]-cy;
          cand[idx][0]=Math.max(margin,Math.min(1-margin,cx+dx*ca-dy*sa));
          cand[idx][1]=Math.max(margin,Math.min(1-margin,cy+dx*sa+dy*ca));
        }
      }
    } else {
      const a=Math.floor(Math.random()*n);
      let b=Math.floor(Math.random()*n);
      while(b===a)b=Math.floor(Math.random()*n);
      const tx=cand[a][0],ty=cand[a][1];
      cand[a][0]=cand[b][0];cand[a][1]=cand[b][1];
      cand[b][0]=tx;cand[b][1]=ty;
    }

    computeRadii(cand);
    let candSum=sum(cand);

    if(candSum>bestSum+tiny){
      bestSum=candSum;
      best=cand.map(c=>[...c]);
      current=cand.map(c=>[...c]);
      curSum=candSum;
      stuck=0;
      if(Date.now()-lastLog>5000){trace.push([(Date.now()-t0)/1000,bestSum]);lastLog=Date.now();}
    } else if(candSum>curSum){
      current=cand.map(c=>[...c]);curSum=candSum;stuck=0;
    } else if(Math.random()<Math.exp((candSum-curSum)/Math.max(temp,1e-7))){
      current=cand.map(c=>[...c]);curSum=candSum;stuck++;
    } else {
      stuck++;
    }

    temp=Math.max(5e-7,temp*0.99997);
    if(stuck>2000){
      current=best.map(c=>[...c]);curSum=bestSum;temp=8e-5;stuck=0;
    }
    if(iter%2000===0&&Date.now()-lastLog>5000){trace.push([(Date.now()-t0)/1000,bestSum]);lastLog=Date.now();}
  }

  // Polish
  const refined=best.map(c=>[...c]);
  computeRadii(refined);
  let refinedSum=sum(refined);

  const steps=[1e-4,5e-5,2e-5,1e-5,5e-6,2e-6,1e-6,5e-7];
  for(let si=0;si<steps.length&&Date.now()-t0<LIMIT;si++){
    const step=steps[si];
    let improved=true,pc=0;
    while(improved&&pc<8&&Date.now()-t0<LIMIT){
      improved=false;pc++;
      for(let i=0;i<n;i++){
        const ox=refined[i][0],oy=refined[i][1];
        let lb=refinedSum,bm=null;
        for(let d=0;d<32;d++){
          const nx=Math.max(margin,Math.min(1-margin,ox+dirs[d][0]*step));
          const ny=Math.max(margin,Math.min(1-margin,oy+dirs[d][1]*step));
          const test=refined.map(c=>[...c]);
          test[i][0]=nx;test[i][1]=ny;
          computeRadii(test);
          const ts=sum(test);
          if(ts>lb+tiny){lb=ts;bm=[nx,ny];}
        }
        if(bm){
          refined[i][0]=bm[0];refined[i][1]=bm[1];
          refinedSum=lb;improved=true;
        }
      }
    }
  }

  computeRadii(refined);
  refinedSum=sum(refined);
  if(refinedSum>bestSum+tiny){
    best=refined.map(c=>[...c]);bestSum=refinedSum;
  }

  // Safety repair
  for(let it=0;it<5;it++){
    let ch=false;
    for(let i=0;i<n;i++){
      const c=best[i];
      let r=Math.min(c[0],1-c[0],c[1],1-c[1])-margin;
      for(let j=0;j<n;j++){
        if(j===i)continue;
        const dx=c[0]-best[j][0],dy=c[1]-best[j][1];
        const d=Math.sqrt(dx*dx+dy*dy);
        const lim=d-best[j][2]-margin;
        if(lim<r)r=lim;
      }
      if(r<1e-12)r=1e-12;
      if(r<c[2]-tiny){c[2]=r;ch=true;}
    }
    if(!ch)break;
  }

  trace.push([(Date.now()-t0)/1000,sum(best)]);
  return {solution:best,trace:trace};
}

